/**
 * Client-side APIs for calling your
 * [Queries](https://wasp.sh/docs/features/data/operations/queries) and
 * [Actions](https://wasp.sh/docs/features/data/operations/actions).
 *
 * Wasp generates one export for each Query and Action you declare, named
 * after it (e.g., `getFoo` for a Query declared as `getFoo`). Each Query
 * export is a {@link Query}, and each Action export is an {@link Action}.
 *
 * The client-side function takes a single optional argument: an object
 * containing any serializable data you wish to use inside the Operation. Wasp
 * sends this object over the network and passes it into the Operation's
 * implementation as its first positional argument. The usage doesn't change
 * depending on whether the Operation uses auth or not: Wasp authenticates the
 * logged-in user in the background.
 *
 * To call Queries and Actions from server code, use `wasp/server/operations`
 * instead.
 *
 * @example
 * ```ts
 * import { getAllTasks, getFilteredTasks, createTask } from "wasp/client/operations";
 *
 * // TypeScript automatically infers the return values and type-checks
 * // the payloads.
 * const allTasks = await getAllTasks();
 * const doneTasks = await getFilteredTasks({ isDone: true });
 * const newTask = await createTask({ description: "Learn TypeScript" });
 * ```
 *
 * @module
 */

import type { QueryClientConfig, UseQueryResult } from "@tanstack/react-query";
import type { Route } from "@wasp.sh/lib-sdk-core";

/**
 * Calls a Query from a React component and keeps its result up to date.
 *
 * Wasp's `useQuery` hook is a thin wrapper around the `useQuery` hook from
 * [_react-query_](https://tanstack.com/query/v4/docs/framework/react/reference/useQuery).
 * One key difference is that Wasp doesn't expect you to supply the cache key:
 * it takes care of it under the hood.
 *
 * Wasp invalidates the Query's cache automatically when you call an Action
 * that uses the same Entities (see
 * [Cache Invalidation](https://wasp.sh/docs/features/data/operations/actions#cache-invalidation)).
 *
 * When a Query fails, `useQuery` retries it a few times before giving up.
 * Client errors like `401` or `404` are the exception: retrying won't change
 * the result, so `useQuery` reports them right away. To change this, set
 * `retry` in `options` for a single Query, or for all Queries with
 * {@link configureQueryClient}.
 *
 * @param query The client-side Query function generated by Wasp based on a
 * `query` spec in your Wasp file, imported from `wasp/client/operations`.
 * @param queryArgs The arguments object (payload) you wish to pass into the
 * Query. The Query's Node.js implementation will receive this object as its
 * first positional argument.
 * @param options A _react-query_ `options` object. Use this to change
 * [the default behavior](https://tanstack.com/query/v4/docs/framework/react/guides/important-defaults)
 * for this particular Query. If you want to change the global defaults, use
 * {@link configureQueryClient}.
 * @returns _react-query_'s `useQuery` result, with the Query's return value in
 * `data`.
 *
 * @example
 * ```tsx
 * import { type Task } from "wasp/entities";
 * import { useQuery, getAllTasks, getFilteredTasks } from "wasp/client/operations";
 *
 * const MainPage = () => {
 *   // TypeScript automatically infers return values and type-checks payload types.
 *   const { data: allTasks, error: error1 } = useQuery(getAllTasks);
 *   const { data: doneTasks, error: error2 } = useQuery(getFilteredTasks, {
 *     isDone: true,
 *   });
 *
 *   if (error1 !== null || error2 !== null) {
 *     return <div>There was an error</div>;
 *   }
 *
 *   return (
 *     <div>
 *       <h2>All Tasks</h2>
 *       {allTasks && allTasks.length > 0
 *         ? allTasks.map((task) => <Task key={task.id} {...task} />)
 *         : "No tasks"}
 *
 *       <h2>Finished Tasks</h2>
 *       {doneTasks && doneTasks.length > 0
 *         ? doneTasks.map((task) => <Task key={task.id} {...task} />)
 *         : "No finished tasks"}
 *     </div>
 *   );
 * };
 *
 * const Task = ({ description, isDone }: Task) => {
 *   return (
 *     <div>
 *       <p>
 *         <strong>Description: </strong>
 *         {description}
 *       </p>
 *       <p>
 *         <strong>Is done: </strong>
 *         {isDone ? "Yes" : "No"}
 *       </p>
 *     </div>
 *   );
 * };
 *
 * export default MainPage;
 * ```
 *
 * You don't need to annotate the Query's return value type. Wasp
 * automatically infers it from the Query's backend implementation. This is
 * **full-stack type safety**: the types on the client always match the types
 * on the server.
 *
 * @see [The `useQuery` hook](https://wasp.sh/docs/features/data/operations/queries#the-usequery-hook)
 */
export declare function useQuery<Input, Output>(
  query: Query<Input, Output>,
  queryArgs?: Input,
  options?: any,
): UseQueryResult<Output, Error>;

/**
 * Adds extra behavior to an Action, like optimistic updates.
 *
 * Make sure you understand how
 * [Queries](https://wasp.sh/docs/features/data/operations/queries) and
 * [Cache Invalidation](https://wasp.sh/docs/features/data/operations/actions#cache-invalidation)
 * work before using it.
 *
 * Since Actions don't require reactivity, you don't need this hook to call
 * them: you can call them directly. The hook returns a function whose API
 * matches the original Action while also doing something extra under the
 * hood (depending on how you configure it).
 *
 * Currently, it only supports specifying optimistic updates (see
 * {@link OptimisticUpdateDefinition}).
 *
 * Wasp's optimistic update API is deliberately small and focuses exclusively
 * on updating Query caches (as that's the most common use case). If you need
 * an API that offers more options or a higher level of control, use
 * _react-query_'s `useMutation` hook and directly work with
 * [their low-level API](https://tanstack.com/query/v4/docs/framework/react/guides/optimistic-updates).
 * You'll need the Query cache key for it, which you can get from any Query's
 * `queryCacheKey` property (see {@link QueryMetadata}).
 *
 * @param action The Wasp Action (the client-side Action function generated by
 * Wasp based on an Action spec) you wish to enhance, imported from
 * `wasp/client/operations`.
 * @param actionOptions An object configuring the extra features you want to
 * add to the given Action. While this argument is technically optional, there
 * is no point in using the `useAction` hook without providing it (it would be
 * the same as using the Action directly). It supports the following fields:
 *
 * - `optimisticUpdates`: An array of objects where each object defines an
 *   [optimistic update](https://stackoverflow.com/a/33009713) to perform on the
 *   Query cache. See {@link OptimisticUpdateDefinition}.
 *
 * @returns A function with the same API as `action`, with the added behavior.
 *
 * @example
 * Configure the Action `markTaskAsDone`, which sets a task's `isDone` status,
 * to perform an optimistic update:
 *
 * ```tsx
 * import React from "react";
 * import { type Task } from "wasp/entities";
 * import {
 *   useQuery,
 *   useAction,
 *   type OptimisticUpdateDefinition,
 *   getTask,
 *   markTaskAsDone,
 * } from "wasp/client/operations";
 *
 * type TaskPayload = Pick<Task, "id">;
 *
 * const TaskPage = ({ id }: { id: number }) => {
 *   const { data: task } = useQuery(getTask, { id });
 *   // TypeScript automatically type-checks the payload type.
 *   const markTaskAsDoneOptimistically = useAction(markTaskAsDone, {
 *     optimisticUpdates: [
 *       {
 *         getQuerySpecifier: ({ id }) => [getTask, { id }],
 *         updateQuery: (_payload, oldData) => ({ ...oldData, isDone: true }),
 *       } as OptimisticUpdateDefinition<TaskPayload, Task>,
 *     ],
 *   });
 *
 *   if (!task) {
 *     return <h1>"Loading"</h1>;
 *   }
 *
 *   const { description, isDone } = task;
 *   return (
 *     <div>
 *       <p>
 *         <strong>Description: </strong>
 *         {description}
 *       </p>
 *       <p>
 *         <strong>Is done: </strong>
 *         {isDone ? "Yes" : "No"}
 *       </p>
 *       {isDone || (
 *         <button onClick={() => markTaskAsDoneOptimistically({ id })}>
 *           Mark as done.
 *         </button>
 *       )}
 *     </div>
 *   );
 * };
 *
 * export default TaskPage;
 * ```
 *
 * @see [Using Actions on the client](https://wasp.sh/docs/features/data/operations/actions#using-actions-on-the-client)
 */
export declare function useAction<Input = unknown, Output = unknown>(
  action: Action<Input, Output>,
  actionOptions?: ActionOptions<Input>,
): Action<Input, Output>;

/**
 * Configures _react-query_'s `QueryClient`, which Wasp's {@link useQuery}
 * uses under the hood.
 *
 * _react-query_ comes configured with aggressive but sane default options, so
 * you most likely won't have to change those defaults for all Queries. Wasp
 * adjusts the retry configuration so that Queries failing with a client error,
 * like `401` or `404`, aren't retried (see
 * [Error Handling](https://wasp.sh/docs/features/data/operations/queries#error-handling)).
 * If you set `defaultOptions.queries.retry`, it replaces Wasp's default.
 *
 * Call it in your
 * [client setup function](https://wasp.sh/docs/advanced/client-customization/client-config#setup-function),
 * before Wasp creates the `QueryClient`. Calling it afterwards throws an
 * error.
 *
 * To change the options for a **single** Query, pass them to
 * {@link useQuery} instead.
 *
 * @param config An object expected by the `QueryClient`'s constructor, as
 * explained in
 * [react-query's docs](https://tanstack.com/query/v4/docs/reference/QueryClient).
 *
 * @example
 * ```ts
 * import { configureQueryClient } from "wasp/client/operations";
 *
 * export default async function mySetupFunction(): Promise<void> {
 *   // ... some setup
 *   configureQueryClient({
 *     defaultOptions: {
 *       queries: {
 *         staleTime: Infinity,
 *       },
 *     },
 *   });
 *   // ... some more setup
 * }
 * ```
 *
 * @see [Overriding default behaviour for Queries](https://wasp.sh/docs/advanced/client-customization/client-config#overriding-default-behaviour-for-queries)
 */
export declare function configureQueryClient(config: QueryClientConfig): void;

/**
 * Defines an [optimistic update](https://stackoverflow.com/a/33009713) for
 * {@link useAction}: how to update a Query's cached data before the Action
 * finishes.
 *
 * The `updateQuery` function must be a pure function. It must return the
 * desired cache value identified by the `getQuerySpecifier` function and
 * _must not_ perform any side effects.
 *
 * Also, make sure you only update the Query caches affected by your Action
 * causing the optimistic update (Wasp cannot yet verify this).
 *
 * Finally, your implementation of the `updateQuery` function should work
 * correctly regardless of the state of `oldData` (e.g., don't rely on array
 * positioning). If you need to do something else during your optimistic
 * update, you can directly use _react-query_'s lower-level API (see
 * {@link useAction}).
 *
 * @typeParam ActionInput The type of the Action's input payload.
 * @typeParam CachedData The type of the Query's cached data.
 *
 * @example
 * ```ts
 * import { type Task } from "wasp/entities";
 * import { type OptimisticUpdateDefinition, getTask } from "wasp/client/operations";
 *
 * const markTaskAsDoneUpdate = {
 *   getQuerySpecifier: ({ id }) => [getTask, { id }],
 *   updateQuery: (_payload, oldData) => ({ ...oldData, isDone: true }),
 * } as OptimisticUpdateDefinition<Pick<Task, "id">, Task>;
 * ```
 */
export type OptimisticUpdateDefinition<ActionInput, CachedData> = {
  /**
   * A function returning the Query specifier (a value used to address the
   * Query you want to update). A Query specifier is an array specifying the
   * Query function and arguments.
   *
   * For example, to optimistically update the Query used with
   * `useQuery(fetchFilteredTasks, { isDone: true })`, your
   * `getQuerySpecifier` function would have to return the array
   * `[fetchFilteredTasks, { isDone: true }]`.
   *
   * @param item The argument you pass into the decorated Action. You can use
   * the properties of the added/changed item to address the Query.
   */
  getQuerySpecifier: (item: ActionInput) => QuerySpecifier<unknown, CachedData>;
  /**
   * The function used to perform the optimistic update. It should return the
   * desired state of the cache.
   *
   * @param item The argument you pass into the decorated Action.
   * @param oldData The currently cached value for the Query identified by the
   * specifier.
   */
  updateQuery: (
    item: ActionInput,
    oldData: CachedData | undefined,
  ) => CachedData;
};

/**
 * The extra properties (metadata) found on every {@link Query}.
 */
export type QueryMetadata = {
  /**
   * The key _react-query_ uses for caching the Query's results.
   *
   * Wasp uses it internally but abstracts it from you. You need it if you use
   * _react-query_'s API directly (e.g., its `useMutation` hook for optimistic
   * updates that {@link useAction} doesn't support).
   *
   * @example
   * ```ts
   * import { getTasks } from "wasp/client/operations";
   *
   * const queryKey = getTasks.queryCacheKey;
   * ```
   */
  queryCacheKey: string[];
  /**
   * The HTTP route of the Query's API endpoint.
   */
  route: Route;
};

/**
 * The type of the client-side function for calling a Query.
 *
 * Wasp generates one such export for each Query you declare, named after it
 * (e.g., `getFoo` for a Query declared as `getFoo`). Import it from
 * `wasp/client/operations`.
 *
 * Call it directly to fetch the Query's data once, or pass it to
 * {@link useQuery} to keep the data up to date in a React component. It's a
 * function with some extra properties (see {@link QueryMetadata}).
 *
 * In TypeScript, its `Input` and `Output` types come from the Query's
 * server-side implementation: you only need to specify the Query's type in its
 * server-side definition, and the client code will automatically know its API
 * payload types (**full-stack type safety**).
 *
 * This type itself isn't exported from `wasp/client/operations`.
 *
 * @typeParam Input The type of the Query's input payload.
 * @typeParam Output The type of the Query's return value.
 *
 * @example
 * ```ts
 * import { getAllTasks, getFilteredTasks } from "wasp/client/operations";
 *
 * const allTasks = await getAllTasks();
 * const doneTasks = await getFilteredTasks({ isDone: true });
 * ```
 *
 * @see [Using Queries on the client](https://wasp.sh/docs/features/data/operations/queries#using-queries-on-the-client)
 */
export type Query<Input, Output> = QueryFunction<Input, Output> & QueryMetadata;

/**
 * The type of the client-side function for calling an Action.
 *
 * Wasp generates one such export for each Action you declare, named after it
 * (e.g., `createFoo` for an Action declared as `createFoo`). Import it from
 * `wasp/client/operations`.
 *
 * Call it directly, or enhance it with {@link useAction}. Calling it
 * invalidates the cache of the Queries that use the same Entities (see
 * [Cache Invalidation](https://wasp.sh/docs/features/data/operations/actions#cache-invalidation)).
 *
 * In TypeScript, its `Input` and `Output` types come from the Action's
 * server-side implementation (**full-stack type safety**).
 *
 * This type itself isn't exported from `wasp/client/operations`.
 *
 * @typeParam Input The type of the Action's input payload.
 * @typeParam Output The type of the Action's return value.
 *
 * @example
 * ```ts
 * import { createTask, markTaskAsDone } from "wasp/client/operations";
 *
 * const newTask = await createTask({ description: "Learn TypeScript" });
 * await markTaskAsDone({ id: 1 });
 * ```
 *
 * @see [Using Actions on the client](https://wasp.sh/docs/features/data/operations/actions#using-actions-on-the-client)
 */
export type Action<Input, Output> =
  // `Input` is `any`
  0 extends 1 & Input
    ? (args?: any) => Promise<Output>
    : [Input] extends [never]
      ? (args?: unknown) => Promise<Output>
      : [Input] extends [void]
        ? () => Promise<Output>
        : (args: Input) => Promise<Output>;

/**
 * The function you call to run a Query from the client (the same as an
 * {@link Action}).
 *
 * It takes the Query's payload as its only argument (or no arguments, if
 * the Query's `Input` type is `void`), and returns a `Promise` with the
 * Query's result.
 *
 * @typeParam Input The type of the Query's input payload.
 * @typeParam Output The type of the Query's return value.
 */
type QueryFunction<Input, Output> =
  // `Input` is `any`
  0 extends 1 & Input
    ? (args?: any) => Promise<Output>
    : [Input] extends [never]
      ? (args?: unknown) => Promise<Output>
      : [Input] extends [void]
        ? () => Promise<Output>
        : (args: Input) => Promise<Output>;

/**
 * The options for {@link useAction}.
 *
 * @typeParam ActionInput The type of the Action's input payload.
 */
type ActionOptions<ActionInput> = {
  /**
   * An array of objects where each object defines an
   * [optimistic update](https://stackoverflow.com/a/33009713) to perform on
   * the Query cache.
   */
  optimisticUpdates: OptimisticUpdateDefinition<ActionInput, any>[];
};

/**
 * A value used to address a Query in the cache: an array with the Query
 * function, followed by its arguments (e.g., `[getTask, { id: 1 }]`).
 *
 * @typeParam Input The type of the Query's input payload.
 * @typeParam Output The type of the Query's return value.
 */
type QuerySpecifier<Input, Output> = [Query<Input, Output>, ...any[]];

export {};
